using CCStats.Core.Capture;
using CCStats.Core.Library;
using PvpStats.Analysis;
internal static class SettlementChecks {
    public static void Run(Action<bool,string> check) {
        check(MatchModeRules.Name(835)=="练习赛"&&MatchModeRules.Name(850)=="段位赛"&&MatchModeRules.Name(862)=="自定赛"&&MatchModeRules.Name(9999)=="未知","native duty IDs use the original match-type rules without guessing new duties");
        var now=DateTime.UtcNow;
        ReplayBundle Fixture(){var b=new ReplayBundle{Match=new(){StartUtc=now.AddMinutes(-5),EndUtc=now,Observation=true,LocalPlayer="Player0 Ixion"}};for(int i=0;i<10;i++)b.Match.Players.Add(new(){Name=$"Player{i} Ixion",Team=i<5?1:2,Job="骑士"});var nodes=new List<ClientUiText>();void Text(string text,float x,float y)=>nodes.Add(new("root/"+nodes.Count,(uint)nodes.Count,x,y,0x10,text,Array.Empty<byte>()));Text("VICTORY",20,5);var labels=new[]{"Kills","Deaths","Assists","Damage Dealt","Damage Taken","HP Restored","Time on Crystal"};for(int i=0;i<labels.Length;i++)Text(labels[i],250+i*90,30);for(int r=0;r<10;r++){float y=65+r*30;Text($"Player{r}",20,y);var values=new[]{"2","1","5","123,456","234,567","34,567","01:32"};for(int i=0;i<values.Length;i++)Text(values[i],250+i*90,y);}b.ResultPanels.Add(new(now,"PvPResult",new()){TextNodes=nodes});return b;}
        check(SettlementTextProbe.PlainText(new byte[]{2,0x13,2,5,3,65,66})=="AB"&&SettlementTextProbe.PlainText(new byte[]{2,0x13,2})=="","UI formatting payloads are removed without inventing text from malformed bytes");
        var valid=Fixture();check(SettlementDecoder.Apply(valid)&&valid.Match.Players.All(p=>p.Damage==123456&&p.CrystalSeconds==92)&&valid.Match.ScoreboardComplete,"labelled result cells populate all ten official player scores");check(!valid.Match.Observation&&valid.Match.Winner==1&&valid.Match.Result=="胜利","only a verified scoreboard and local outcome promote a match into official statistics");
        var missing=Fixture();missing.ResultPanels[0].TextNodes.RemoveAll(n=>n.Text=="Damage Taken");check(!SettlementDecoder.Apply(missing)&&missing.Match.Players.All(p=>p.Damage==null),"missing column headers cannot turn unlabelled numbers into invented scores");
        var wrong=Fixture();wrong.Match.Players[0].Name="Different Player Ixion";check(!SettlementDecoder.Apply(wrong)&&wrong.Match.Players.All(p=>p.Kills==null),"another match's result panel cannot attach to a mismatched roster");
        var late=Fixture();late.Match.EndUtc=now.AddMinutes(-4);late.Match.StartUtc=now.AddMinutes(-9);check(!SettlementDecoder.Apply(late),"result panels outside the recorded match window are rejected");
        var ambiguous=Fixture();ambiguous.ResultPanels[0].TextNodes.Add(new("duplicate",999,250,65,0x10,"8",Array.Empty<byte>()));check(!SettlementDecoder.Apply(ambiguous)&&ambiguous.Match.Players.All(p=>p.Kills==null),"ambiguous duplicate cells are rejected atomically");
        var overflow=Fixture();var overflowNodes=overflow.ResultPanels[0].TextNodes;for(int i=0;i<overflowNodes.Count;i++)if(overflowNodes[i].Text=="01:32")overflowNodes[i]=overflowNodes[i] with {Text="2147483647:59"};check(!SettlementDecoder.Apply(overflow),"overflow-length crystal times are rejected without integer wraparound");
        var duplicateRoster=Fixture();duplicateRoster.Match.Players[1].Name=duplicateRoster.Match.Players[0].Name;check(!SettlementDecoder.Apply(duplicateRoster),"duplicate roster names cannot attach the same score twice");
        var noOutcome=Fixture();noOutcome.ResultPanels[0].TextNodes.RemoveAll(n=>n.Text=="VICTORY");check(SettlementDecoder.Apply(noOutcome)&&noOutcome.Match.Observation&&noOutcome.Match.Winner==0,"official numeric scores without a local result do not fabricate a victory");
        var scene=new ReplayBundle();scene.Data.Effects.AddRange(new[]{new ObservedEffect{Actor="场地实体 123",Target="Player0 Ixion",ActionId=28726,Type=3,Amount=54000},new ObservedEffect{Actor="场地实体 456",Target="Player1 Ixion",ActionId=28726,Type=3,Amount=30000}});var row=SkillReport.Build(scene).Single();check(row.Player=="爆弹怪"&&row.Name=="自爆"&&row.Damage==84000&&row.Casts==null,"scene hazards are named and grouped without raw entity IDs or fabricated cast counts");
        check(ActionCatalog.Name(29676)=="Wyrmwave"&&ActionCatalog.Name(28726)=="Self-destruct","bundled official action names cover skills and map attacks without numeric-only labels");
        check(ReplayEventReport.Build(scene).Length==2&&ReplayEventReport.Build(scene).All(e=>e.Actor=="爆弹怪"),"timeline includes real effect events with named scene sources");
        check(SkillReport.Name(29676)=="真龙波","autonomous summon actions resolve a display name instead of a skill number");
        var roster=new ReplayBundle();roster.Match.Players.Add(new(){Name="Own"});roster.Data.Frames.Add(new(){Players=new(){new(){Player="Own",Team=0}}});roster.Data.Frames.Add(new(){Players=new(){new(){Player="Own",Team=1}}});ReplayRoster.Reconcile(roster);check(roster.Match.Players[0].Team==1&&roster.Data.Frames[0].Players[0].Team==1,"a later uniquely confirmed roster repairs unknown team labels in saved frames");
    }
}
